function gtDate(s){
  var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s).trim());
  if(!m) return null;
  var d=Date.UTC(+m[1], +m[2]-1, +m[3]);
  var chk=new Date(d);
  if(chk.getUTCMonth()!==+m[2]-1||chk.getUTCDate()!==+m[3]) return null;
  return d;
}
function gtParse(text){
  if(typeof text!=='string'||!text.trim()) return { value:null, error:'任务表为空' };
  var lines=text.split('\n'), tasks=[];
  for(var i=0;i<lines.length;i++){
    var line=lines[i].trim();
    if(!line||line.charAt(0)==='#') continue;
    var parts=line.split(/[,，]/).map(function(s){ return s.trim(); });
    if(parts.length<3) return { value:null, error:'第 '+(i+1)+' 行: 至少需要 任务名, 开始日, 天数' };
    var start=gtDate(parts[1]);
    if(start===null) return { value:null, error:'第 '+(i+1)+' 行: 日期格式应为 YYYY-MM-DD' };
    var days=Number(parts[2]);
    if(!isFinite(days)||days<1||days!==Math.floor(days)) return { value:null, error:'第 '+(i+1)+' 行: 天数必须是正整数' };
    var prog=parts.length>3?Number(parts[3]):0;
    if(!isFinite(prog)||prog<0||prog>100) return { value:null, error:'第 '+(i+1)+' 行: 进度须在 0-100' };
    tasks.push({ name:parts[0], start:start, days:days, progress:prog });
  }
  if(!tasks.length) return { value:null, error:'没有有效任务行' };
  return { value:tasks, error:null };
}
var GT_DAY=86400000;
function gtStats(tasks){
  var min=Infinity, max=-Infinity, i;
  for(i=0;i<tasks.length;i++){
    if(tasks[i].start<min) min=tasks[i].start;
    var end=tasks[i].start+tasks[i].days*GT_DAY;
    if(end>max) max=end;
  }
  var total=Math.round((max-min)/GT_DAY);
  var wsum=0, dsum=0;
  for(i=0;i<tasks.length;i++){ wsum+=tasks[i].progress*tasks[i].days; dsum+=tasks[i].days; }
  return { minStart:min, maxEnd:max, spanDays:total,
    weightedProgress:Math.round(wsum/dsum*100)/100 };
}
function gtOverlaps(tasks){
  var out=[];
  for(var i=0;i<tasks.length;i++)
    for(var j=i+1;j<tasks.length;j++){
      var aEnd=tasks[i].start+tasks[i].days*GT_DAY, bEnd=tasks[j].start+tasks[j].days*GT_DAY;
      if(tasks[i].start<bEnd && aEnd>tasks[j].start) out.push([tasks[i].name, tasks[j].name]);
    }
  return out;
}
function gtEsc(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function gtSvg(text){
  var p=gtParse(text);
  if(p.error) return { value:null, error:p.error };
  var tasks=p.value, st=gtStats(tasks);
  var LEFT=150, ROW=34, DAYW=Math.max(18, Math.min(46, Math.floor(560/Math.max(st.spanDays,1))));
  var W=LEFT+st.spanDays*DAYW+30, H=46+tasks.length*ROW+26;
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  for(var d=0;d<=st.spanDays;d++){
    var gx=LEFT+d*DAYW;
    s+='<line x1="'+gx+'" y1="40" x2="'+gx+'" y2="'+(H-20)+'" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>';
    if(d<st.spanDays && (st.spanDays<=14 || d%2===0)){
      var dd=new Date(st.minStart+d*GT_DAY);
      s+='<text x="'+(gx+DAYW/2)+'" y="32" text-anchor="middle" font-size="9" fill="#71717A" font-family="system-ui,sans-serif">'+(dd.getUTCMonth()+1)+'/'+dd.getUTCDate()+'</text>';
    }
  }
  for(var i=0;i<tasks.length;i++){
    var t=tasks[i], y=46+i*ROW;
    var x=LEFT+Math.round((t.start-st.minStart)/GT_DAY)*DAYW, w=t.days*DAYW;
    s+='<text x="'+(LEFT-10)+'" y="'+(y+15)+'" text-anchor="end" font-size="12" fill="#FFFFFF" font-family="system-ui,sans-serif">'+gtEsc(t.name.length>10?t.name.slice(0,9)+'…':t.name)+'</text>';
    s+='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="20" rx="5" fill="#1A1B1E" stroke="rgba(255,255,255,0.14)"/>';
    if(t.progress>0) s+='<rect x="'+x+'" y="'+y+'" width="'+Math.round(w*t.progress/100)+'" height="20" rx="5" fill="'+(t.progress>=100?'#10B981':'#5E6AD2')+'"/>';
    s+='<text x="'+(x+w+6)+'" y="'+(y+15)+'" font-size="10" fill="#A1A1AA" font-family="system-ui,sans-serif">'+t.progress+'%</text>';
  }
  s+='<text x="'+LEFT+'" y="'+(H-6)+'" font-size="11" fill="#A1A1AA" font-family="system-ui,sans-serif">总跨度 '+st.spanDays+' 天 · 加权进度 '+st.weightedProgress+'%</text>';
  s+='</svg>';
  return { value:s, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { gtDate:gtDate, gtParse:gtParse, gtStats:gtStats, gtOverlaps:gtOverlaps, gtSvg:gtSvg, gtEsc:gtEsc };
}
if (typeof window !== 'undefined') {
  window.GanttForgePure = { gtDate:gtDate, gtParse:gtParse, gtStats:gtStats, gtOverlaps:gtOverlaps, gtSvg:gtSvg, gtEsc:gtEsc };
}
